#!/usr/bin/env python3
"""One-off cleanup tool for build artifacts."""
import sys
from pathlib import Path


def main(argv):
    if not argv:
        print("usage: cleanup.py <target-dir>")
        return 2

    target_path = Path(argv[0]).resolve()
    deleted = 0
    for path in sorted(target_path.rglob("*")):
        if path.is_file():
            path.unlink()
            deleted += 1
            print("[cleanup] deleted " + str(path))

    print("[cleanup] deleted %d file(s)" % deleted)
    return 0


if __name__ == "__main__":
