## 2. Manifest schema

Every plugin ships a `plugin.manifest.json` validated against this JSON Schema at publish
time and at load time (defense in depth — a registry compromise shouldn't be the only gate).

```json
{
  "$id": "https://internal/schemas/plugin-manifest-v1.json",
  "type": "object",
  "required": ["id", "name", "version", "apiVersion", "entryPoint", "capabilities", "permissions", "sandbox"],
  "properties": {
    "id": { "type": "string", "pattern": "^[a-z0-9][a-z0-9-]{2,63}$" },
    "name": { "type": "string" },
    "version": { "type": "string", "pattern": "^\\d+\\.\\d+\\.\\d+(-[\\w.]+)?$" },
    "apiVersion": { "type": "string", "description": "semver RANGE against host API, e.g. ^3.2" },
    "team": { "type": "string", "description": "owning team, for the approval/audit trail" },
    "description": { "type": "string" },
    "entryPoint": { "type": "string", "description": "path to compiled bundle inside package" },
    "engine": { "enum": ["node", "python", "subprocess"], "default": "node" },
    "capabilities": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["type", "export"],
        "properties": {
          "type": { "enum": ["datasource", "transform", "visualization", "exporter", "trigger", "authprovider"] },
          "export": { "type": "string", "description": "named export implementing the provider interface" },
          "id": { "type": "string", "description": "capability id, unique within the plugin" },
          "configSchema": { "type": "object", "description": "JSON Schema for this capability's runtime config" }
        }
      }
    },
    "permissions": {
      "type": "object",
      "properties": {
        "network": {
          "type": "array",
          "items": { "type": "string" },
          "description": "allow-listed hosts, e.g. 'api.salesforce.com:443'"
        },
        "secrets": {
          "type": "array",
          "items": { "type": "string" },
          "description": "secret key patterns this plugin may read, e.g. 'salesforce/*'"
        },
        "filesystem": { "enum": ["none", "scratch"], "default": "none" },
        "storage": { "type": "boolean", "description": "grants scoped KV store access (platform.storage)", "default": false }
      },
      "additionalProperties": false
    },
    "sandbox": {
      "type": "object",
      "required": ["tier"],
      "properties": {
        "tier": { "enum": ["isolate", "process"] },
        "memoryLimitMb": { "type": "integer", "default": 256 },
        "cpuTimeMs": { "type": "integer", "default": 30000, "description": "per-call wall clock timeout" },
        "concurrency": { "type": "integer", "default": 4 }
      }
    },
    "dependencies": {
      "type": "object",
      "description": "other plugin ids this plugin requires, semver range",
      "additionalProperties": { "type": "string" }
    },
    "signature": { "type": "string", "description": "detached signature over the packed tarball, filled by publish step" }
  }
}
