  "id": "salesforce-datasource",
  "name": "Salesforce Data Source",
  "version": "1.4.0",
  "apiVersion": "^3.2",
  "team": "growth-reporting",
  "entryPoint": "dist/index.js",
  "capabilities": [
    {
